// Kisrhombille lattice adjacency (see SPEC_002_KRB and geometry.py).
// Every fundamental triangle has exactly 3 edge-neighbors: 2 in the same
// hex (always sectors (s-1+12)%12 and (s+1)%12) and 1 cross-hex neighbor.
// The cross-hex table below is generated by
// scripts/generate_lattice_tables.py from the tested Python geometry
// module — do not hand-edit; regenerate and re-paste if the lattice ever
// changes.

export const NUM_SECTORS = 12;
export const SQRT3 = Math.sqrt(3.0);
export const SECTOR_ANGLE = Math.PI / 6.0;

// Generated by scripts/generate_lattice_tables.py — do not hand-edit.
// For sector i: the one edge-neighbor not in the same hex, as (dq, dr, targetSector).
// The other 2 neighbors are always sectors (i - 1 + 12) % 12 and (i + 1) % 12 in the same hex.
export const CROSS_HEX_NEIGHBOR = [
  { dq: 1, dr: 0, sector: 5 }, // sector 0
  { dq: 0, dr: 1, sector: 8 }, // sector 1
  { dq: 0, dr: 1, sector: 7 }, // sector 2
  { dq: -1, dr: 1, sector: 10 }, // sector 3
  { dq: -1, dr: 1, sector: 9 }, // sector 4
  { dq: -1, dr: 0, sector: 0 }, // sector 5
  { dq: -1, dr: 0, sector: 11 }, // sector 6
  { dq: 0, dr: -1, sector: 2 }, // sector 7
  { dq: 0, dr: -1, sector: 1 }, // sector 8
  { dq: 1, dr: -1, sector: 4 }, // sector 9
  { dq: 1, dr: -1, sector: 3 }, // sector 10
  { dq: 1, dr: 0, sector: 6 }, // sector 11
];

