/** Flattened `[dq, dr, sector]` ints for all 12 sectors, ready for a `uniform ivec3[12]`. */
export function crossHexNeighborUniformData() {
  const data = new Int32Array(12 * 3);
  for (let sector = 0; sector < NUM_SECTORS; sector++) {
    const entry = CROSS_HEX_NEIGHBOR[sector];
    data[sector * 3 + 0] = entry.dq;
    data[sector * 3 + 1] = entry.dr;
    data[sector * 3 + 2] = entry.sector;
  }
  return data;
}

export const NUM_VERTEX_NEIGHBORS_PER_SECTOR = 13;

/** Flattened `[dq, dr, sector]` ints for all 12 sectors x 13 vertex-neighbors, ready for a `uniform ivec3[12 * 13]`. */
export function vertexNeighborUniformData() {
  const data = new Int32Array(NUM_SECTORS * NUM_VERTEX_NEIGHBORS_PER_SECTOR * 3);
  for (let sector = 0; sector < NUM_SECTORS; sector++) {
    const entries = VERTEX_NEIGHBOR[sector];
    for (let i = 0; i < NUM_VERTEX_NEIGHBORS_PER_SECTOR; i++) {
      const base = (sector * NUM_VERTEX_NEIGHBORS_PER_SECTOR + i) * 3;
      data[base + 0] = entries[i].dq;
      data[base + 1] = entries[i].dr;
      data[base + 2] = entries[i].sector;
    }
  }
  return data;
}
